-- Verify the operations of timestamptz that need a time zone, which ty's zones
-- (ty/DESIGN.md section 20) serve: the casts, AT TIME ZONE, the fields, the
-- truncation, the arithmetic across a daylight time, and the text. The session's
-- zone changes; the instants are around the transitions of several zones.
SET datestyle = 'ISO, MDY';
SET timezone = 'UTC';
SELECT i, i::timestamptz AS tz, (i::timestamptz)::timestamp AS ts, (i::timestamptz)::date AS d, (i::timestamptz)::timetz AS ttz, to_char(i::timestamptz, 'YYYY-MM-DD HH24:MI:SS TZ OF') AS fmt FROM (VALUES ('1900-01-01 00:00:00+00'), ('1970-01-01 00:00:00+00'), ('2000-04-02 06:59:59+00'), ('2000-04-02 07:00:00+00'), ('2000-10-29 05:59:59+00'), ('2000-10-29 06:00:00+00'), ('2024-03-10 06:59:59+00'), ('2024-03-10 07:00:00+00'), ('2024-03-31 00:59:59+00'), ('2024-03-31 01:00:00+00'), ('2024-10-27 00:59:59+00'), ('2024-10-27 01:00:00+00'), ('2024-04-06 14:59:59+00'), ('2024-04-06 15:00:00+00'), ('2011-12-30 09:59:59+00'), ('2011-12-30 10:00:00+00'), ('2037-12-31 23:59:59+00'), ('2100-07-01 12:00:00+00'), ('infinity'), ('-infinity')) v(i);
SELECT i, (i::timestamp)::timestamptz AS tz, i::timestamp AT TIME ZONE 'America/New_York' AS ny, i::timestamp AT TIME ZONE 'EST' AS est, i::timestamp AT TIME ZONE 'EDT' AS edt, i::timestamp AT TIME ZONE 'MSK' AS msk, i::timestamp AT TIME ZONE '+03:30' AS plus, i::timestamp AT TIME ZONE INTERVAL '-2 hours' AS iv FROM (VALUES ('2000-04-02 01:59:59'), ('2000-04-02 02:00:00'), ('2000-04-02 02:30:00'), ('2000-04-02 03:00:00'), ('2000-10-29 00:59:59'), ('2000-10-29 01:00:00'), ('2000-10-29 01:30:00'), ('2000-10-29 02:00:00'), ('2024-03-10 02:30:00'), ('2024-11-03 01:30:00'), ('2024-03-31 01:30:00'), ('2024-10-27 01:30:00'), ('2024-04-07 02:15:00'), ('2011-12-30 12:00:00'), ('1500-06-01 12:00:00'), ('2100-07-01 12:00:00'), ('infinity'), ('-infinity')) v(i);
SELECT i, i::timestamptz AT TIME ZONE 'America/New_York' AS ny, i::timestamptz AT TIME ZONE 'Europe/London' AS lon, i::timestamptz AT TIME ZONE 'EST' AS est, i::timestamptz AT TIME ZONE 'EDT' AS edt, i::timestamptz AT TIME ZONE 'MSK' AS msk, i::timestamptz AT TIME ZONE 'UTC+3' AS posix, i::timestamptz AT TIME ZONE INTERVAL '5:30' AS iv, i::timestamptz AT LOCAL AS loc FROM (VALUES ('1900-01-01 00:00:00+00'), ('1970-01-01 00:00:00+00'), ('2000-04-02 06:59:59+00'), ('2000-04-02 07:00:00+00'), ('2000-10-29 05:59:59+00'), ('2000-10-29 06:00:00+00'), ('2024-03-10 06:59:59+00'), ('2024-03-10 07:00:00+00'), ('2024-03-31 00:59:59+00'), ('2024-03-31 01:00:00+00'), ('2024-10-27 00:59:59+00'), ('2024-10-27 01:00:00+00'), ('2024-04-06 14:59:59+00'), ('2024-04-06 15:00:00+00'), ('2011-12-30 09:59:59+00'), ('2011-12-30 10:00:00+00'), ('2037-12-31 23:59:59+00'), ('2100-07-01 12:00:00+00'), ('infinity'), ('-infinity')) v(i);
SELECT i, extract(epoch FROM i::timestamptz) AS epoch, extract(hour FROM i::timestamptz) AS h, extract(timezone FROM i::timestamptz) AS tz, extract(timezone_hour FROM i::timestamptz) AS tzh, extract(timezone_minute FROM i::timestamptz) AS tzm, extract(dow FROM i::timestamptz) AS dow, extract(doy FROM i::timestamptz) AS doy, extract(julian FROM i::timestamptz) AS jul, date_part('week', i::timestamptz) AS wk, date_part('isoyear', i::timestamptz) AS iy FROM (VALUES ('1900-01-01 00:00:00+00'), ('1970-01-01 00:00:00+00'), ('2000-04-02 06:59:59+00'), ('2000-04-02 07:00:00+00'), ('2000-10-29 05:59:59+00'), ('2000-10-29 06:00:00+00'), ('2024-03-10 06:59:59+00'), ('2024-03-10 07:00:00+00'), ('2024-03-31 00:59:59+00'), ('2024-03-31 01:00:00+00'), ('2024-10-27 00:59:59+00'), ('2024-10-27 01:00:00+00'), ('2024-04-06 14:59:59+00'), ('2024-04-06 15:00:00+00'), ('2011-12-30 09:59:59+00'), ('2011-12-30 10:00:00+00'), ('2037-12-31 23:59:59+00'), ('2100-07-01 12:00:00+00'), ('infinity'), ('-infinity')) v(i) WHERE i NOT LIKE '%infinity';
