SELECT i, date_trunc('hour', i::timestamptz) AS h, date_trunc('day', i::timestamptz) AS d, date_trunc('week', i::timestamptz) AS w, date_trunc('month', i::timestamptz) AS m, date_trunc('year', i::timestamptz) AS y, date_trunc('day', i::timestamptz, 'Asia/Tokyo') AS dz, date_trunc('month', i::timestamptz, 'Europe/London') AS mz FROM (VALUES ('1900-01-01 00:00:00+00'), ('1970-01-01 00:00:00+00'), ('2000-04-02 06:59:59+00'), ('2000-04-02 07:00:00+00'), ('2000-10-29 05:59:59+00'), ('2000-10-29 06:00:00+00'), ('2024-03-10 06:59:59+00'), ('2024-03-10 07:00:00+00'), ('2024-03-31 00:59:59+00'), ('2024-03-31 01:00:00+00'), ('2024-10-27 00:59:59+00'), ('2024-10-27 01:00:00+00'), ('2024-04-06 14:59:59+00'), ('2024-04-06 15:00:00+00'), ('2011-12-30 09:59:59+00'), ('2011-12-30 10:00:00+00'), ('2037-12-31 23:59:59+00'), ('2100-07-01 12:00:00+00'), ('infinity'), ('-infinity')) v(i) WHERE i NOT LIKE '%infinity';
SELECT i, i::timestamptz + interval '1 day' AS d1, i::timestamptz + interval '24 hours' AS h24, i::timestamptz + interval '1 month' AS m1, i::timestamptz - interval '1 month 1 day' AS mm, date_add(i::timestamptz, interval '1 day', 'Asia/Tokyo') AS dz, date_subtract(i::timestamptz, interval '1 month', 'Europe/London') AS sz FROM (VALUES ('1900-01-01 00:00:00+00'), ('1970-01-01 00:00:00+00'), ('2000-04-02 06:59:59+00'), ('2000-04-02 07:00:00+00'), ('2000-10-29 05:59:59+00'), ('2000-10-29 06:00:00+00'), ('2024-03-10 06:59:59+00'), ('2024-03-10 07:00:00+00'), ('2024-03-31 00:59:59+00'), ('2024-03-31 01:00:00+00'), ('2024-10-27 00:59:59+00'), ('2024-10-27 01:00:00+00'), ('2024-04-06 14:59:59+00'), ('2024-04-06 15:00:00+00'), ('2011-12-30 09:59:59+00'), ('2011-12-30 10:00:00+00'), ('2037-12-31 23:59:59+00'), ('2100-07-01 12:00:00+00'), ('infinity'), ('-infinity')) v(i) WHERE i NOT LIKE '%infinity' AND i NOT LIKE '294276%' AND i NOT LIKE '%BC';
SELECT a, b, age(a::timestamptz, b::timestamptz) AS age, a::timestamptz - b::timestamptz AS diff, date_bin(interval '6 hours', a::timestamptz, timestamptz '2000-01-01 00:00:00+00') AS bin FROM (VALUES ('2024-03-11 12:00:00+00','2024-03-09 12:00:00+00'), ('2024-11-04 12:00:00+00','2024-11-02 12:00:00+00'), ('2000-01-31 12:00:00+00','1999-12-01 12:00:00+00'), ('2024-03-31 12:00:00+00','2024-03-30 12:00:00+00')) v(a, b);
SELECT make_timestamptz(2024, 3, 10, 2, 30, 0) AS gap, make_timestamptz(2024, 11, 3, 1, 30, 0) AS fold, make_timestamptz(2024, 3, 31, 1, 30, 0, 'Europe/London') AS lon, make_timestamptz(2000, 6, 15, 12, 0, 0, 'Asia/Tokyo') AS tok, make_timestamptz(1500, 6, 15, 12, 0, 0) AS old;
SELECT i::date::timestamptz AS dtz, i::date < i::timestamptz AS lt, i::timestamptz = i::date AS eq, (i::timestamptz)::time AS t, (i::timestamptz)::timetz AS ttz, time '04:05:06' AT TIME ZONE 'Asia/Tokyo' AS tt, timetz '04:05:06+02' AT TIME ZONE 'America/New_York' AS ttz_ny, timetz '04:05:06+02' AT TIME ZONE INTERVAL '3 hours' AS ttz_iv FROM (VALUES ('1900-01-01 00:00:00+00'), ('1970-01-01 00:00:00+00'), ('2000-04-02 06:59:59+00'), ('2000-04-02 07:00:00+00'), ('2000-10-29 05:59:59+00'), ('2000-10-29 06:00:00+00'), ('2024-03-10 06:59:59+00'), ('2024-03-10 07:00:00+00'), ('2024-03-31 00:59:59+00'), ('2024-03-31 01:00:00+00'), ('2024-10-27 00:59:59+00'), ('2024-10-27 01:00:00+00'), ('2024-04-06 14:59:59+00'), ('2024-04-06 15:00:00+00'), ('2011-12-30 09:59:59+00'), ('2011-12-30 10:00:00+00'), ('2037-12-31 23:59:59+00'), ('2100-07-01 12:00:00+00'), ('infinity'), ('-infinity')) v(i) WHERE i NOT LIKE '%infinity' AND i NOT LIKE '294276%' AND i NOT LIKE '%BC';
SELECT s::text, s::timestamp AS local FROM generate_series(timestamptz '2024-03-09 12:00:00+00', timestamptz '2024-03-12 12:00:00+00', interval '1 day') s;
SELECT s::text FROM generate_series(timestamptz '2024-10-26 12:00:00+00', timestamptz '2024-10-29 12:00:00+00', interval '1 day', 'Europe/London') s;
SELECT '2024-03-10 02:30:00'::timestamptz AS gap, '2024-11-03 01:30:00'::timestamptz AS fold, '2024-07-01 12:00:00 EDT'::timestamptz AS edt, '2024-07-01 12:00:00 America/New_York'::timestamptz AS ny, '2024-07-01 12:00:00 MSK'::timestamptz AS msk;
SET timezone = 'UTC';
SELECT i, i::timestamptz AS tz, (i::timestamptz)::timestamp AS ts, (i::timestamptz)::date AS d FROM (VALUES ('4713-01-01 00:00:00+00 BC'), ('294276-12-31 23:59:59+00'), ('infinity')) v(i);
SET timezone = 'America/New_York';
SELECT now() = (now()::timestamp AT TIME ZONE 'America/New_York') AS roundtrip;
SELECT count(*) > 500 AS many, count(*) FILTER (WHERE name = 'America/New_York') AS has_ny, min(utc_offset) <= interval '-11 hours' AS west, max(utc_offset) >= interval '14 hours' AS east FROM pg_timezone_names();
SELECT name FROM pg_timezone_names() WHERE name IN ('America/New_York', 'Europe/London', 'Asia/Kolkata', 'UTC', 'Australia/Lord_Howe') ORDER BY name;
